                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                        <label class="form-check-label" for="compactMode">
                            <strong>Compact Mode</strong>
                            <div class="text-muted small">Reduce spacing and padding throughout the UI</div>
                        </label>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @if (_saving)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Save
                </button>
            </div>

            <div class="col-md-6">
                <h6 class="fw-semibold mb-3">Live Preview</h6>
                <div class="preview-area border rounded p-3"
                     style="@PreviewStyle()">
                    <div class="mb-2" style="font-weight:600;">Sample Heading</div>
                    <p style="margin-bottom: @(_compactMode ? "0.25rem" : "0.75rem");">
                        This is a preview of how your content will appear with the selected settings.
                    </p>
                    <div class="d-flex gap-2" style="margin-top: @(_compactMode ? "0.25rem" : "0.5rem");">
                        <span class="badge" style="@BadgeStyle()">Badge</span>
                        <span class="badge" style="@BadgeStyle()">Label</span>
                    </div>
                    <div style="margin-top: @(_compactMode ? "0.5rem" : "1rem");">
                        <button class="btn btn-sm" style="@ButtonPreviewStyle()">Sample Button</button>
                    </div>
                    <div class="text-muted mt-2" style="font-size:0.75em;">
                        Theme: @_theme · Font: @_fontSize · Language: @_language · Compact: @(_compactMode ? "On" : "Off")
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _saving;
    private string? _statusMessage;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        await SettingsService.SaveAppearanceAsync(new AppearanceSettings(_theme, _fontSize, _language, _compactMode));
        _saving = false;
        _statusMessage = "Appearance settings saved!";
    }

    private string GetFontSizeCss() => _fontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.15rem",
        _ => "1rem"
    };

