    {
        var bg = _theme == "Dark" ? "#1e1e1e" : "#ffffff";
        var fg = _theme == "Dark" ? "#e0e0e0" : "#212529";
        var padding = _compactMode ? "0.75rem" : "1.25rem";
        return $"background:{bg}; color:{fg}; font-size:{GetFontSizeCss()}; padding:{padding}; transition: all 0.2s ease;";
    }

    private string BadgeStyle()
    {
        var bg = _theme == "Dark" ? "#4a9eff" : "#0d6efd";
        return $"background:{bg}; color:#fff;";
    }

    private string ButtonPreviewStyle()
    {
        var bg = _theme == "Dark" ? "#333" : "#f8f9fa";
        var fg = _theme == "Dark" ? "#e0e0e0" : "#212529";
        var border = _theme == "Dark" ? "#555" : "#dee2e6";
        return $"background:{bg}; color:{fg}; border: 1px solid {border};";
    }
}
