@using sv_70609a6b8e0b42c3b5aca594831e01b1.Services

<div class="card mb-3">
    <div class="card-body">
        <h5 class="card-title mb-3">Active Sessions</h5>
        <div class="table-responsive">
            <table class="table table-hover align-middle mb-0">
                <thead class="table-light">
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Sessions)
                    {
                        var isCurrent = session.Id == CurrentSessionId;
                        <tr>
                            <td>
                                @session.Device
                                @if (isCurrent)
                                {
                                    <span class="badge bg-success ms-2">Current</span>
                                }
                            </td>
                            <td>@session.Location</td>
                            <td>@FormatTime(session.LastActive)</td>
                            <td class="text-end">
                                @if (!isCurrent)
                                {
                                    <button class="btn btn-outline-danger btn-sm"
                                            @onclick="() => OnRevokeRequested.InvokeAsync(session.Id)">
                                        Revoke
                                    </button>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    </div>
</div>

@code {
    [Parameter] public List<ActiveSession> Sessions { get; set; } = [];
    [Parameter] public string CurrentSessionId { get; set; } = "sess-1";
    [Parameter] public EventCallback<string> OnRevokeRequested { get; set; }

    private static string FormatTime(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

@using sv_70609a6b8e0b42c3b5aca594831e01b1.Services

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Security</h4>

        <ChangePasswordPanel OnChangePassword="HandleChangePasswordAsync" />

        <div class="card mb-3">
            <div class="card-body d-flex justify-content-between align-items-center">
                <div>
                    <h5 class="mb-1">Two-Factor Authentication</h5>
                    <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="twoFactor"
                           checked="@_twoFactorEnabled"
                           @onchange="e => _twoFactorEnabled = (bool)(e.Value ?? false)"
                           style="transform: scale(1.3);" />
                </div>
            </div>
            @if (_lastPasswordChange.HasValue)
            {
                <div class="card-footer text-muted small">
                    Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")
                </div>
            }
        </div>

        <ActiveSessionsTable Sessions="_sessions"
                             CurrentSessionId="sess-1"
                             OnRevokeRequested="RequestRevoke" />

        @if (_sessionToRevoke is not null)
        {
            <RevokeSessionDialog OnConfirm="ConfirmRevokeAsync" OnCancel="CancelRevoke" />
        }
    </div>
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = [];
    private string? _sessionToRevoke;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = settings.Sessions.ToList();
    }

    private async Task HandleChangePasswordAsync((string Current, string New) args)
    {
        await SettingsService.ChangePasswordAsync(args.Current, args.New);
        _lastPasswordChange = DateTime.UtcNow;
    }

    private void RequestRevoke(string sessionId) => _sessionToRevoke = sessionId;
    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke);
            _sessions.RemoveAll(s => s.Id == _sessionToRevoke);
            _sessionToRevoke = null;
        }
    }
}

